<?php require __DIR__.'/config.php';$rows=db()->query("SELECT member_no,checked_at FROM qr_test_attendance ORDER BY checked_at DESC")->fetchAll();?>
<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>참석자 명부</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:800px"><div class="d-flex justify-content-between align-items-center"><div><h1 class="h3 fw-bold mb-1">QR 참석자 명부</h1><p class="text-secondary">현재 <?=count($rows)?>명</p></div><div><a href="scan.php" class="btn btn-dark">스캔 화면</a> <a href="index.php" class="btn btn-outline-dark">QR 생성</a></div></div><div class="card shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>#</th><th>조합원번호</th><th>참석시각</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><?=count($rows)-$i?></td><td class="fw-bold"><?=h($r['member_no'])?></td><td><?=h($r['checked_at'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="3" class="text-center py-5 text-secondary">아직 참석자가 없습니다.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>
